from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin, field_options
@dataclass
class C(DataClassDictMixin):
 x:int
@dataclass
class P(DataClassDictMixin):
 c:C=field(default_factory=lambda:C(7), metadata=field_options(flatten=True,flatten_prefix=True))
assert P.from_dict({}) == P(C(7))
assert P.from_dict({'c_x':2}) == P(C(2))
@dataclass
class O(DataClassDictMixin):
 c:Optional[C]=field(default=None,metadata=field_options(flatten=True,flatten_prefix=True))
assert O.from_dict({}) == O(None)
assert O.from_dict({'c_x':2}) == O(C(2))
print('default and optional cases passed')
